/**
 * Domains to ignore - tracking, ads, analytics, CDNs, etc.
 */
const IGNORED_DOMAINS = new Set([
  'doubleclick.net', 'googlesyndication.com', 'googleadservices.com', 'adsrvr.org',
  'adnxs.com', 'criteo.com', 'taboola.com', 'outbrain.com',
  'google.com', 'google-analytics.com', 'googletagmanager.com', 'segment.com',
  'mixpanel.com', 'hotjar.com', 'amplitude.com', 'rlcdn.com', 'rubiconproject.com',
  'cloudflare.com', 'akamai.com', 'fastly.com', 'amazonaws.com', 'cloudfront.net',
  'accounts.google.com', 'login.microsoftonline.com', 'auth0.com',
  'facebook.net', 'fbcdn.net', 'licdn.com', 'bing.com', 'yahoo.com',
  'demdex.net', 'quantserve.com', 'scorecardresearch.com',
]);

const SESSION_COOKIE_PATTERNS = [
  'session', 'token', 'auth', 'user', 'login', 'sid', 'logged',
  'credential', 'identity', 'account', 'jwt', 'access', 'refresh',
];

/** Extract the root domain from a cookie domain. ".www.reddit.com" -> "reddit.com" */
function getRootDomain(cookieDomain) {
  let domain = cookieDomain.replace(/^\./, '');
  const parts = domain.split('.');
  if (parts.length >= 3) {
    const lastTwo = parts.slice(-2).join('.');
    const lastThree = parts.slice(-3).join('.');
    if (lastTwo === 'ycombinator.com') {
      return lastThree;
    }
    return lastTwo;
  }
  return domain;
}

/** Check if a cookie looks like a session/auth cookie. */
function isSessionCookie(cookie) {
  const name = cookie.name.toLowerCase();
  if (SESSION_COOKIE_PATTERNS.some(pattern => name.includes(pattern))) {
    return true;
  }
  if (cookie.httpOnly) {
    return true;
  }
  if (cookie.secure && cookie.expires && cookie.expires > 0) {
    const expiresDate = new Date(cookie.expires * 1000);
    const daysUntilExpiry = (expiresDate - new Date()) / (1000 * 60 * 60 * 24);
    if (daysUntilExpiry > 7) {
      return true;
    }
  }
  return false;
}

/** Check if any cookies for a domain are still valid (not expired). */
function hasValidCookies(cookies) {
  return cookies.some(cookie => {
    if (!cookie.expires || cookie.expires === -1) {
      return true;
    }
    return cookie.expires * 1000 > Date.now();
  });
}

/**
 * Detect logged-in platforms from a Playwright-style storage state.
 * @param {object} storageState - { cookies: [...], origins: [...] }
 * @returns {Array<object>} Detected platforms with hints
 */
export function detectLoggedInPlatforms(storageState) {
  const cookies = storageState.cookies || [];
  if (cookies.length === 0) {
    return [];
  }

  const domainCookies = new Map();
  for (const cookie of cookies) {
    const rootDomain = getRootDomain(cookie.domain);
    if (!domainCookies.has(rootDomain)) {
      domainCookies.set(rootDomain, []);
    }
    domainCookies.get(rootDomain).push(cookie);
  }

  const detectedPlatforms = [];
  for (const [domain, domainCookieList] of domainCookies) {
    if (IGNORED_DOMAINS.has(domain)) {
      continue;
    }
    const sessionCookies = domainCookieList.filter(isSessionCookie);
    if (sessionCookies.length === 0) {
      continue;
    }
    if (!hasValidCookies(sessionCookies)) {
      continue;
    }

    const knownPlatform = KNOWN_PLATFORMS[domain];
    if (knownPlatform) {
      detectedPlatforms.push({
        domain,
        name: knownPlatform.name,
        homeUrl: knownPlatform.homeUrl,
        hints: knownPlatform.hints,
        algorithmTips: knownPlatform.algorithmTips || [],
        cookieCount: domainCookieList.length,
        sessionCookieCount: sessionCookies.length,
        isKnown: true,
      });
    } else {
      detectedPlatforms.push({
        domain,
        name: formatDomainAsName(domain),
        homeUrl: `https://${domain}`,
        hints: [
          'Navigate to the homepage and explore the site structure',
          'Look for a search function to find relevant discussions',
          'Find community areas, forums, or comment sections',
          'Search for keywords related to your products',
          'Look for help sections or Q&A areas',
        ],
        cookieCount: domainCookieList.length,
        sessionCookieCount: sessionCookies.length,
        isKnown: false,
      });
    }
  }

  detectedPlatforms.sort((a, b) => {
    if (a.isKnown !== b.isKnown) {
      return a.isKnown ? -1 : 1;
    }
    return b.sessionCookieCount - a.sessionCookieCount;
  });

  return detectedPlatforms;
}

/** Format a domain as a readable platform name. "example-site.com" -> "Example Site" */
function formatDomainAsName(domain) {
  const name = domain.replace(/\.(com|org|net|io|co|app|dev|ai|xyz|me)$/, '');
  return name
    .split(/[.-]/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

/** Get platform info for a specific domain. */
export function getPlatformByDomain(domain) {
  const rootDomain = getRootDomain(domain);
  return KNOWN_PLATFORMS[rootDomain] || null;
}

/** Generate suggested search queries from products and platform. */
export function suggestSearchQueries(products, platform) {
  const queries = new Set();
  for (const product of products) {
    if (product.tags) {
      for (const tag of product.tags) {
        queries.add(tag.toLowerCase());
      }
    }
    if (product.name) {
      queries.add(product.name.toLowerCase());
    }
  }
  return Array.from(queries).slice(0, 15);
}
